import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        final double epsilon = 1e-15;
        Scanner scanner = new Scanner(System.in);
        int a = 0, b = 0;
        double t, t1;
        int x = scanner.nextInt();
        int y = scanner.nextInt();
        int n = scanner.nextInt();

        t1 = (double) x / y;
        t = 1 + (double) x / y;

        for (int i = 1; i <= n; ++i) {
            double ratio1 = (double) ((int) (t1 * i)) / i;
            double diff1 = Math.abs(ratio1 - t1);
            if (!(diff1 > t - epsilon && diff1 < t + epsilon)) {
                if (diff1 < t) {
                    t = diff1;
                    a = (int) ((double) x / y * i);
                    b = i;
                }
            }
            double ratio2 = (double) ((int) (t1 * i + 1)) / i;
            double diff2 = Math.abs(ratio2 - t1);
            if (!(diff2 > t - epsilon && diff2 < t + epsilon)) {
                if (diff2 < t) {
                    t = diff2;
                    a = (int) ((double) x / y * i) + 1;
                    b = i;
                }
            }
        }
        System.out.println(a + "/" + b);
        scanner.close();
    }
}
